import React, { useEffect, useState } from "react";
import axios from "axios";
import ForceGraph from "react-force-graph";

const ClusterVisualization = () => {
  const [graphData, setGraphData] = useState({ nodes: [], links: [] });
  const [isLoading, setIsLoading] = useState(true);
  const [lastUpdated, setLastUpdated] = useState(null);

  const fetchData = async () => {
    try {
      const [nodesRes, podsRes] = await Promise.all([
        axios.get("http://localhost:5000/api/nodes"),
        axios.get("http://localhost:5000/api/pods"),
      ]);

      const nodes = Object.values(nodesRes.data);
      const pods = Object.values(podsRes.data);

      // Prepare graph data
      const graphNodes = [];
      const graphLinks = [];

      // Add nodes
      nodes.forEach((node) => {
        graphNodes.push({
          id: node.ID,
          name: `Node ${node.ID.slice(0, 6)}`,
          type: "node",
          status: node.Status,
          cpu: node.CPU,
          availableCPU: node.AvailableCPU,
          val: 10 + node.CPU / 2, // Size based on CPU capacity
        });
      });

      // Add pods and links
      pods.forEach((pod) => {
        graphNodes.push({
          id: pod.ID,
          name: `Pod ${pod.ID.slice(0, 6)}`,
          type: "pod",
          status: pod.Status,
          cpu: pod.CPU,
          val: 5 + pod.CPU / 2, // Size based on CPU request
        });

        if (pod.NodeID) {
          graphLinks.push({
            source: pod.NodeID,
            target: pod.ID,
            value: pod.CPU,
          });
        }
      });

      setGraphData({ nodes: graphNodes, links: graphLinks });
      setLastUpdated(new Date());
      setIsLoading(false);
    } catch (error) {
      console.error("Error fetching data:", error);
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 5000); // Refresh every 5 seconds
    return () => clearInterval(interval);
  }, []);

  const nodeColor = (node) => {
    if (node.type === "node") {
      return node.status === "Running" ? "#4CAF50" : "#F44336"; // Green for running, red for unhealthy
    } else {
      return node.status === "Running" ? "#2196F3" : "#FF9800"; // Blue for running, orange for offline
    }
  };

  const nodeCanvasObject = (node, ctx, globalScale) => {
    const label = node.name;
    const fontSize = 12 / globalScale;
    ctx.font = `${fontSize}px Sans-Serif`;
    const textWidth = ctx.measureText(label).width;
    const bckgDimensions = [textWidth, fontSize].map((n) => n + fontSize * 0.2); // some padding

    // Draw background
    ctx.fillStyle = "rgba(255, 255, 255, 0.8)";
    ctx.fillRect(
      node.x - bckgDimensions[0] / 2,
      node.y - bckgDimensions[1] / 2,
      ...bckgDimensions,
    );

    // Draw text
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillStyle = "#000000";
    ctx.fillText(label, node.x, node.y);

    // Add status indicator
    ctx.fillStyle = nodeColor(node);
    ctx.beginPath();
    ctx.arc(node.x, node.y, node.val / 2, 0, 2 * Math.PI, false);
    ctx.fill();
  };

  return (
    <div style={{ height: "100vh", width: "100%" }}>
      <h2>Docker Cluster Visualization</h2>
      {lastUpdated && <p>Last updated: {lastUpdated.toLocaleTimeString()}</p>}

      {isLoading ? (
        <p>Loading cluster data...</p>
      ) : (
        <ForceGraph2D
          graphData={graphData}
          nodeLabel={(node) => `
            ${node.name}
            Type: ${node.type}
            Status: ${node.status}
            CPU: ${node.cpu} cores
            ${node.type === "node" ? `Available CPU: ${node.availableCPU} cores` : ""}
          `}
          nodeAutoColorBy="type"
          nodeCanvasObject={nodeCanvasObject}
          linkDirectionalArrowLength={3.5}
          linkDirectionalArrowRelPos={1}
          linkCurvature={0.1}
          linkColor={() => "rgba(200, 200, 200, 0.5)"}
        />
      )}
    </div>
  );
};

export default ClusterVisualization;
